import { test, expect } from '@playwright/test';

test.describe('Landing footer and about links', () => {
  test('No link points to "#" on public pages @desktop @prod-safe (#1afa56)', async ({ page }) => {
    const paths = ['/', '/about', '/headhunters', '/talents', '/organizations'];
    for (const path of paths) {
      // 1. Open the page as guest (/, then /about, /headhunters, /talents, /organizations)
      await page.goto(path);
      await expect(page.getByRole('contentinfo')).toBeVisible();

      // 2. Count links with href exactly "#" or ending with "/#"
      const hashLinks = await page.locator('a').evaluateAll((links) =>
        links
          .map((a) => a.getAttribute('href') ?? '')
          .filter((h) => h === '#' || h.endsWith('/#')),
      );
      expect(hashLinks, `hash links on ${path}`).toHaveLength(0);
    }
  });
});
